template <class T>
class SharedPtr {
public:
  SharedPtr() noexcept = default;
  explicit SharedPtr(T* p);
  // copy, move, assignment, destructor, get, *, ->, use_count, reset
};

questions.modelAnswer:
#include <atomic>
#include <cstddef>
#include <utility>

template <class T>
class SharedPtr {
  struct Ctrl { std::atomic<std::size_t> refs{1}; };
  T* p_ = nullptr;
  Ctrl* c_ = nullptr;

  void release() noexcept {
    if (c_ && c_->refs.fetch_sub(1, std::memory_order_acq_rel) == 1) {
      delete p_;
      delete c_;
    }
  }
public:
  SharedPtr() noexcept = default;
  explicit SharedPtr(T* p) : p_(p) {
    if (p_) {
      try { c_ = new Ctrl; }
      catch (...) { delete p_; throw; }   // don't leak p if the control block fails
    }
  }
  SharedPtr(const SharedPtr& o) noexcept : p_(o.p_), c_(o.c_) {
    if (c_) c_->refs.fetch_add(1, std::memory_order_relaxed);
  }
  SharedPtr(SharedPtr&& o) noexcept
      : p_(std::exchange(o.p_, nullptr)), c_(std::exchange(o.c_, nullptr)) {}
  SharedPtr& operator=(SharedPtr o) noexcept {   // copy-and-swap: copy and move, self-safe
    std::swap(p_, o.p_);
    std::swap(c_, o.c_);
    return *this;                                 // o releases the old object
  }
  ~SharedPtr() { release(); }

  void reset(T* p = nullptr) { SharedPtr(p).swap(*this); }
  void swap(SharedPtr& o) noexcept { std::swap(p_, o.p_); std::swap(c_, o.c_); }

  T* get() const noexcept { return p_; }
  T& operator*() const { return *p_; }
  T* operator->() const noexcept { return p_; }
  explicit operator bool() const noexcept { return p_ != nullptr; }
  std::size_t use_count() const noexcept {
    return c_ ? c_->refs.load(std::memory_order_relaxed) : 0;
  }
};

